// The form fields arrive keyed by their labels, so they are read once here and
// everything downstream uses plain names.
//
// single-item input: a form submission is one item.
const f = $('Ask For The Beat').first().json;
const cfg = $('Settings').first().json;

const beat = String(f['Subject or beat'] || '').trim();
const comparables = String(f['Companies like yours'] || '')
  .split(/[|,;]+/)
  .map(function (s) { return s.trim(); })
  .filter(Boolean)
  .slice(0, 3);
const story = String(f['Your story in one line'] || '').trim();
const region = String(f['Region'] || 'us').trim().toLowerCase().slice(0, 2) || 'us';

if (beat.length < 3) {
  throw new Error('Put a subject in the first field, for example "warehouse robotics" or "B2B payments fraud".');
}

return [{ json: {
  beat: beat,
  comparables: comparables,
  comparables_query: comparables.length ? comparables.join(' OR ') : beat,
  story: story,
  region: region,
  max_articles: Math.max(2, Math.min(15, Number(cfg.max_articles) || 8)),
}}];

// Both searches land here through the Merge, which is what guarantees the
// second one has finished before any counting happens.
//
// These are Google News rows. They carry the outlet, the headline and the date
// and are the only reliable way to find journalism rather than vendor content
// marketing - a plain web search for "warehouse robotics" returns Oracle,
// AutoStore and Modula blog posts, which is not a media list. What news rows do
// not carry is a fetchable address, so the URL is resolved a step later.
const NOT_COVERAGE = [
  'pr newswire', 'prnewswire', 'business wire', 'businesswire', 'globenewswire',
  'globe newswire', 'prweb', 'accesswire', 'einpresswire', 'openpr', 'issuewire',
  'facebook', 'instagram', 'linkedin', 'youtube', 'reddit', 'tiktok', 'pinterest',
  'marketsandmarkets', 'researchandmarkets', 'grand view research', 'yahoo finance',
];

function unwrapSerp(x) {
  // `format: json` returns the HTTP envelope with the parsed SERP nested in
  // `body` as a STRING. Reading the results off the top level finds nothing and
  // reports that nobody writes about your subject.
  let p = x;
  if (p && p.body != null) { p = p.body; }
  if (typeof p === 'string') {
    try { p = JSON.parse(p); } catch (e) { p = {}; }
  } else if (p && typeof p.data === 'string') {
    try { p = JSON.parse(p.data); } catch (e) { p = {}; }
  } else if (p && p.data && typeof p.data === 'object') {
    p = p.data;
  }
  return p || {};
}

const req = $('Read The Request').first().json;
const byHeadline = new Map();
let parsedSearches = 0;

for (const item of $input.all()) {
  const parsed = unwrapSerp(item.json);
  const query = String((parsed.general && parsed.general.query) || '');
  // Which of the two searches this row came from, decided by the query rather
  // than by input index - Merge in append mode does not promise an order.
  const fromComparables = req.comparables.length > 0 && query.indexOf(req.comparables_query) >= 0;

  const rows = parsed.news || parsed.organic || [];
  if (rows.length) { parsedSearches += 1; }

  for (const r of rows) {
    const headline = String((r && r.title) || '').trim();
    if (headline.length < 15) { continue; }
    const outlet = String((r && r.source) || '').trim();
    if (!outlet) { continue; }

    const flat = outlet.toLowerCase();
    // Wires are your own industry's press releases coming back at you, and a
    // market-research firm's headline is a report listing, not coverage.
    if (NOT_COVERAGE.some(function (w) { return flat.indexOf(w) >= 0; })) { continue; }

    const key = headline.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
    const existing = byHeadline.get(key) || {
      headline: headline,
      outlet: outlet,
      snippet: String((r && r.description) || '').slice(0, 300),
      published: String((r && r.date) || ''),
      on_beat: false,
      on_comparables: false,
    };
    if (fromComparables) { existing.on_comparables = true; } else { existing.on_beat = true; }
    byHeadline.set(key, existing);
  }
}

const articles = [...byHeadline.values()];

// An outlet writing about your subject AND about companies like yours is the
// better bet, so those sort first. This is the whole reason two searches run.
const outletCount = new Map();
for (const a of articles) {
  outletCount.set(a.outlet, (outletCount.get(a.outlet) || 0) + 1);
}

articles.sort(function (a, b) {
  const sa = (a.on_beat && a.on_comparables ? 4 : 0) + (outletCount.get(a.outlet) > 1 ? 1 : 0);
  const sb = (b.on_beat && b.on_comparables ? 4 : 0) + (outletCount.get(b.outlet) > 1 ? 1 : 0);
  return sb - sa;
});

const chosen = articles.slice(0, req.max_articles);

// A step that can return nothing ends the branch, and the quiet path below it
// would never run. One marker item always comes back.
if (!chosen.length) {
  // Two different reasons look identical from here, and telling them apart is
  // the difference between "nobody writes about this" and "the search did not
  // come back". Both searches returning no rows at all is the second one.
  return [{ json: {
    found_any: false,
    headline: '',
    total: 0,
    reason: parsedSearches === 0
      ? 'Neither search returned any results. That is usually the search rather than the subject, so it is worth running again.'
      : 'Results came back, but every one was a wire service, a market-research listing or a social post. Try a narrower subject.',
  }}];
}
return chosen.map(function (a) {
  return { json: Object.assign({ found_any: true, total: articles.length }, a) };
});

// Runs once for each item: one headline lookup per article.
//
// Google's news tab returns every link as a relative `/goto?url=CAES...`
// redirect wrapper and never as an address - ten of ten rows when measured on
// 2026-08-30 - so the article the news tab found cannot be fetched from the
// news tab. Searching the exact headline in web mode returns the same article
// with a real URL, which is what this reads.
const SOCIAL = [
  'facebook.', 'instagram.', 'linkedin.', 'x.com', 'twitter.', 'youtube.',
  'reddit.', 'tiktok.', 'pinterest.', 'msn.com', 'news.google.',
];

function unwrapSerp(x) {
  let p = x;
  if (p && p.body != null) { p = p.body; }
  if (typeof p === 'string') {
    try { p = JSON.parse(p); } catch (e) { p = {}; }
  } else if (p && typeof p.data === 'string') {
    try { p = JSON.parse(p.data); } catch (e) { p = {}; }
  } else if (p && p.data && typeof p.data === 'object') {
    p = p.data;
  }
  return p || {};
}

const parsed = unwrapSerp($input.item.json);
const article = $('Pick What To Read').item.json;
const rows = parsed.organic || [];

// The outlet name reduced to letters, so "Supply Chain Brain" can be compared
// against supplychainbrain.com.
const outletKey = String(article.outlet || '').toLowerCase().replace(/[^a-z0-9]/g, '');

let best = '';
let fallback = '';
for (const r of rows) {
  const link = String((r && r.link) || '');
  if (!/^https?:\/\//.test(link)) { continue; }
  const host = link.replace(/^https?:\/\//, '').split('/')[0].toLowerCase();
  if (host.indexOf('google.') === 0) { continue; }
  if (SOCIAL.some(function (d) { return host.indexOf(d) >= 0; })) { continue; }

  const hostKey = host.replace(/^www\./, '').split('.')[0].replace(/[^a-z0-9]/g, '');
  if (!best && outletKey && hostKey && (hostKey.indexOf(outletKey) >= 0 || outletKey.indexOf(hostKey) >= 0)) {
    best = link;
  }
  if (!fallback) { fallback = link; }
}

// Preferring the host that matches the outlet keeps a syndicated copy on an
// aggregator from being read in place of the original, which matters because
// the byline is what is being looked for and syndication strips it.
return { json: Object.assign({}, article, {
  link: best || fallback,
  matched_outlet: best ? 'yes' : 'no',
})};

// Runs once for each item: one article page per item.
//
// This reads raw HTML rather than markdown, and the reason is measured. Asked
// for markdown, the WSJ piece came back as 3.5 KB of navigation with no byline
// anywhere in it, because the converter drops the document head - and the head
// is exactly where the byline lives. The same URL as raw HTML carries
// `<meta name="author" content="Liz Young">`. Two of three pages tested gave a
// name from metadata, and none of the three gave one from the prose.
const raw = $input.item.json;
const article = $('Pick The Article URL').item.json;

const html = String(typeof raw === 'string' ? raw : ((raw && (raw.data || raw.body)) || ''));
const head = html.slice(0, 200000);

// Metadata first, prose last. Ordered by how often each one is both present and
// correct, which is not the order they look important in when reading a page.
const PATTERNS = [
  /<meta[^>]+name=["']author["'][^>]*content=["']([^"']{2,80})/i,
  /<meta[^>]+content=["']([^"']{2,80})["'][^>]*name=["']author["']/i,
  /"author"\s*:\s*\{[^}]*?"name"\s*:\s*"([^"]{2,80})"/,
  /"author"\s*:\s*\[\s*\{[^}]*?"name"\s*:\s*"([^"]{2,80})"/,
  /rel=["']author["'][^>]*>([^<]{2,80})</i,
  /(?:^|>|\n)\s*(?:#+\s*)?[Bb]y[:\s]+([A-Z][a-zA-Z.'-]+(?:\s+[A-Z][a-zA-Z.'-]+){1,2})/,
];

// "The Editorial Board", "Staff Writer" and "By Reuters" are outlets wearing a
// person's grammar. A CMS account name like "Apool DS" is let through on
// purpose: it is a poor byline, but it is what that page actually claims.
const NOT_A_PERSON = /^(the|our|a|an|staff|editorial|associated|reuters|bloomberg|admin|guest|team|newsroom)$/i;

function plausible(v) {
  const name = String(v || '').replace(/\s+/g, ' ').trim();
  if (name.length < 4 || name.length > 60) { return ''; }
  if (/\d/.test(name) || name.indexOf('@') >= 0) { return ''; }
  if (/^https?:/.test(name)) { return ''; }
  const words = name.split(' ');
  if (words.length < 2 || words.length > 4) { return ''; }
  if (NOT_A_PERSON.test(words[0])) { return ''; }
  return name;
}

let name = '';
for (const re of PATTERNS) {
  const m = head.match(re);
  if (!m) { continue; }
  const candidate = plausible(m[1]);
  if (candidate) { name = candidate; break; }
}

// article:author is usually a profile URL rather than a name, and the slug
// carries the name: .../news/author/liz-young -> Liz Young.
if (!name) {
  const m = head.match(/article:author["'][^>]*content=["'][^"']*\/author\/([a-z-]{4,60})/i);
  if (m) {
    const guess = m[1].split('-').map(function (w) { return w.charAt(0).toUpperCase() + w.slice(1); }).join(' ');
    name = plausible(guess);
  }
}

const text = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&[a-z]+;/gi, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const key = (name || article.outlet).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

return { json: Object.assign({}, article, {
  name: name,
  person_key: key,
  page_chars: html.length,
  excerpt: text.slice(0, 900),
})};

// One model call, not one per journalist. The ranking is a comparison, so the
// model has to see the whole list at once - and eight separate calls would each
// be paying full price to rank a list of one.
const req = $('Read The Request').first().json;
const rows = $input.all().map(function (i) { return i.json; });

const candidates = rows.map(function (r) {
  return [
    r.name || '(no byline)',
    r.outlet,
    r.headline,
    r.excerpt.slice(0, 400),
  ].join(' | ');
}).join('\n');

return [{ json: {
  candidates: candidates,
  count: rows.length,
  beat: req.beat,
  story: req.story,
}}];

