// The model is asked for JSON and usually returns it, sometimes inside a code
// fence and occasionally cut off mid-sentence when the answer runs long.
//
// A truncated answer is the interesting case. Parsing the whole string fails,
// so the naive version returns nothing and a run that found four journalists
// reports none. Complete `{...}` objects are collected one at a time instead
// and the incomplete tail is dropped, which turns a cut-off answer into a
// shorter list rather than an empty one.
//
// single-item input: one ranking call, one answer.
const raw = String(($input.first().json || {}).text || '');
const rows = $('Find The Journalist').all().map(function (i) { return i.json; });

function objectsIn(text) {
  const out = [];
  // Every open brace is remembered and every matching close is parsed, at any
  // depth. Collecting only top-level objects looks equivalent and is not: when
  // the answer is cut off, the outer wrapper never closes, so a top-level-only
  // scan returns nothing at all while the individual records inside it are
  // sitting there complete.
  const stack = [];
  let inString = false;
  let escaped = false;
  for (let i = 0; i < text.length; i += 1) {
    const c = text[i];
    if (inString) {
      if (escaped) { escaped = false; }
      else if (c === '\\') { escaped = true; }
      else if (c === '"') { inString = false; }
      continue;
    }
    if (c === '"') { inString = true; continue; }
    if (c === '{') { stack.push(i); continue; }
    if (c === '}' && stack.length) {
      const s = stack.pop();
      try { out.push(JSON.parse(text.slice(s, i + 1))); } catch (e) { /* skip */ }
    }
  }
  return out;
}

// The wrapper object parses first when the answer is whole; when it is not,
// the individual person objects inside it still do.
const found = objectsIn(raw);
let people = [];
for (const o of found) {
  if (Array.isArray(o.people)) { people = o.people; break; }
}
if (!people.length) {
  people = found.filter(function (o) { return o && (o.name || o.outlet) && o.angle; });
}

// The ranking is matched back to the article rows by name, then by outlet. The
// model is not asked to carry the URL through - a link it has to retype is a
// link it can get wrong.
function findRow(p) {
  const n = String(p.name || '').toLowerCase();
  const o = String(p.outlet || '').toLowerCase();
  return rows.find(function (r) { return r.name && r.name.toLowerCase() === n; })
    || rows.find(function (r) { return String(r.outlet).toLowerCase() === o; })
    || {};
}

const out = people.map(function (p, i) {
  const row = findRow(p);
  return {
    person_key: row.person_key || String(p.name || p.outlet || ('unknown-' + i)).toLowerCase().replace(/[^a-z0-9]+/g, '-'),
    name: String(p.name || row.name || row.outlet || '').slice(0, 120),
    outlet: String(p.outlet || row.outlet || '').slice(0, 120),
    beat: $('Read The Request').first().json.beat,
    why: String(p.why || '').slice(0, 300),
    angle: String(p.angle || '').slice(0, 400),
    last_headline: String(row.headline || '').slice(0, 200),
    last_url: String(row.link || ''),
    rank: Number(p.rank) || (i + 1),
    // The reason this name is on the list at all: found on your subject, on
    // companies like yours, or - the one worth calling first - on both.
    reach: row.on_beat && row.on_comparables ? 'your subject and your category'
      : row.on_comparables ? 'writes about companies like yours'
      : 'writes about your subject',
    found_on: new Date().toISOString().slice(0, 10),
  };
});

out.sort(function (a, b) { return a.rank - b.rank; });

if (!out.length) {
  return [{ json: {
    has_people: false,
    reason: 'The ranking step came back without a usable answer. Everything up to it worked, so running it again usually fixes it.',
  }}];
}
return out.map(function (p) { return { json: Object.assign({ has_people: true }, p) }; });

// The Docs insert writes the string it is handed - markdown is not parsed, so
// `## Heading` would arrive on the page as those characters. The layout here is
// made of line breaks and capitals for that reason.
//
// Read The Shortlist emits one item per person, so this carries executeOnce:
// without it the document would be created once per row.
const req = $('Read The Request').first().json;
const people = $('Read The Shortlist').all()
  .map(function (i) { return i.json; })
  .filter(function (p) { return p && p.has_people; });

const lines = ['MEDIA LIST: ' + req.beat.toUpperCase(), ''];
if (req.story) { lines.push('Pitching: ' + req.story, ''); }
lines.push('Built ' + new Date().toISOString().slice(0, 10) + ' from ' + people.length + ' journalists publishing on this subject.', '');
lines.push('');

people.forEach(function (p, i) {
  const label = String(p.name || p.outlet || 'Unattributed');
  lines.push((i + 1) + '. ' + label.toUpperCase() + ' - ' + p.outlet + ' (' + p.reach + ')');
  if (p.why) { lines.push('   Covers: ' + p.why); }
  if (p.last_headline) { lines.push('   Last piece: ' + p.last_headline); }
  if (p.last_url) { lines.push('   ' + p.last_url); }
  if (p.angle) { lines.push('   Open with: ' + p.angle); }
  lines.push('');
});

lines.push('');
lines.push('No email addresses are collected here on purpose. Approach each outlet the way it asks to be approached.');

const html = ['<h2>Media list: ' + req.beat + '</h2>']
  .concat(people.map(function (p, i) {
    return '<p><strong>' + (i + 1) + '. ' + String(p.name || p.outlet || 'Unattributed') + '</strong> - ' + p.outlet
      + ' <em>(' + p.reach + ')</em><br>' + p.why
      + (p.last_url ? '<br><a href="' + p.last_url + '">' + p.last_headline + '</a>' : '')
      + '<br><strong>Open with:</strong> ' + p.angle + '</p>';
  }))
  .join('');

return [{ json: {
  title: 'Media list - ' + req.beat,
  body: lines.join('\n'),
  html: html,
  people: people.length,
}}];
